const tenantContext = new AsyncLocalStorage();
async function setDatabaseContext(client, context) {
  await client.query("SELECT set_config('app.workshop_id',$1,false), set_config('app.platform_admin',$2,false)", [context?.workshopId ? String(context.workshopId) : '', context?.platformAdmin ? 'true' : 'false']);
}
async function resetDatabaseContext(client) {
  await client.query("SELECT set_config('app.workshop_id','',false), set_config('app.platform_admin','false',false)");
}
const pool = {
  async query(...args) {
    const context = tenantContext.getStore();
    if (!context) return basePool.query(...args);
    const client = await basePool.connect();
    try { await setDatabaseContext(client, context); return await client.query(...args); }
    finally { try { await resetDatabaseContext(client); } finally { client.release(); } }
  },
  async connect() {
    const context = tenantContext.getStore();
    const client = await basePool.connect();
    if (context) await setDatabaseContext(client, context);
    const release = client.release.bind(client);
    if (context) client.release = (...args) => { resetDatabaseContext(client).catch(err => console.error('Database context reset failed:',err.message)).finally(() => release(...args)); };
    return client;
  },
  end: (...args) => basePool.end(...args)
};

