app.use(async(req,res,next)=>{
  if(!req.session.user)return next();
  if(req.session.user.mustChangePassword&&!['/password/change','/logout','/healthz'].includes(req.path))return res.redirect('/password/change');
  if(['/license-expired','/password/change','/logout','/healthz'].includes(req.path))return next();
  try {
    const active=await pool.query("SELECT 1 FROM licenses l JOIN workshops w ON w.id=l.workshop_id WHERE l.workshop_id=$1 AND w.status='active' AND l.status='active' AND l.starts_at<=now() AND l.expires_at>now() LIMIT 1",[req.session.user.workshopId]);
    if(!active.rowCount){req.session.destroy(()=>res.redirect('/license-expired'));return;}
    next();
  } catch(error){next(error);}
});
