app.get('/reports.csv',needAuth,allow('owner','admin','manager'),async(req,res,next)=>{try{const from=/^\\d{4}-\\d{2}-\\d{2}$/.test(req.query.from||'')?req.query.from:new Date(Date.now()-30*86400000).toISOString().slice(0,10),to=/^\\d{4}-\\d{2}-\\d{2}$/.test(req.query.to||'')?req.query.to:new Date().toISOString().slice(0,10);const q=await pool.query(`SELECT i.issue_date,i.invoice_number,c.name AS customer,v.plate,coalesce(sum(l.quantity*l.unit_price*(1+l.vat_rate/100)),0)::numeric AS total,coalesce((SELECT sum(p.amount) FROM payments p WHERE p.invoice_id=i.id),0)::numeric AS paid,i.status FROM invoices i JOIN work_orders w ON w.id=i.work_order_id JOIN customers c ON c.id=w.customer_id JOIN vehicles v ON v.id=w.vehicle_id LEFT JOIN invoice_lines l ON l.invoice_id=i.id WHERE i.issue_date BETWEEN $1::date AND $2::date GROUP BY i.id,c.name,v.plate ORDER BY i.issue_date,i.id`,[from,to]);const csvCell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';res.type('text/csv; charset=utf-8').set('Content-Disposition','attachment; filename="go-report.csv"').send(['data;numero;cliente;targa;totale;incassato;residuo;stato',...q.rows.map(r=>[r.issue_date,r.invoice_number,r.customer,r.plate,money(r.total),money(r.paid),money(Number(r.total)-Number(r.paid)),r.status].map(csvCell).join(';'))].join('\\r\\n'));}catch(e){next(e);}});
