app.get('/invoices/:id',needAuth,allow('owner','admin','manager','accounting','accountant'),async(req,res,next)=>{try{const q=await pool.query(`SELECT i.*,c.name AS customer,v.plate,v.make,v.model,v.mileage AS vehicle_mileage FROM invoices i JOIN work_orders w ON w.id=i.work_order_id JOIN customers c ON c.id=w.customer_id JOIN vehicles v ON v.id=w.vehicle_id WHERE i.id=$1`,[req.params.id]);if(!q.rowCount)return res.sendStatus(404);const i=q.rows[0];const [lines,pays,total]=await Promise.all([pool.query('SELECT * FROM invoice_lines WHERE invoice_id=$1 ORDER BY id',[i.id]),pool.query('SELECT * FROM payments WHERE invoice_id=$1 ORDER BY paid_at',[i.id]),pool.query('SELECT coalesce(sum(quantity*unit_price*(1+vat_rate/100)),0)::numeric AS amount FROM invoice_lines WHERE invoice_id=$1',[i.id])]);const grand=Number(total.rows[0].amount),paid=pays.rows.reduce((n,p)=>n+Number(p.amount),0),due=Math.max(0,grand-paid);const lineRows=lines.rows.map(l=>`<tr><td>${esc(l.description)}</td><td>${Number(l.quantity)}</td><td>${money(l.unit_price)}</td><td>${l.vat_rate}%</td><td>${money(Number(l.quantity)*Number(l.unit_price)*(1+Number(l.vat_rate)/100))}</td></tr>`).join('');const payRows=pays.rows.map(p=>`<tr><td>${fmtDate(p.paid_at)}</td><td>${esc(p.method)}</td><td>${money(p.amount)}</td><td>${esc(p.reference)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Nessun pagamento</td></tr>';const deliver=['owner','admin','manager','reception'].includes(req.session.user.role)&&i.status==='paid'?`<section class="card"><form method="post" action="/work-orders/${i.work_order_id}/deliver">${formToken(req)}<h2>Consegna veicolo</h2><div class="form-grid">${input('Consegnato a','received_by','text','',true)}${input('Km alla consegna','mileage_out','number',String(i.vehicle_mileage),true)}</div><label>Note consegna<textarea name="notes"></textarea></label><button class="button primary">Registra consegna</button><p class="muted">Verifica persona che ritira e chilometraggio prima di confermare.</p></form></section>`:'';const body=`${takeFlash(req)}<section class="card"><div class="section-heading"><div><span class="eyebrow">DOCUMENTO GESTIONALE · NON FISCALE</span><h2>${esc(i.invoice_number)}</h2><p class="muted">${esc(i.customer)} · ${esc(i.plate)} ${esc(i.make)} ${esc(i.model)}</p></div><a class="button" href="/invoices/${i.id}/pdf">PDF stampabile</a></div><div class="table-wrap"><table><thead><tr><th>Descrizione</th><th>Q.tà</th><th>Prezzo</th><th>IVA</th><th>Totale riga</th></tr></thead><tbody>${lineRows}</tbody></table></div><div class="totals"><strong>Totale: ${money(grand)}</strong><strong>Pagato: ${money(paid)}</strong><strong>Residuo: ${money(due)}</strong></div>${i.status==='draft'?`<form method="post" action="/invoices/${i.id}/issue">${formToken(req)}<button class="button primary">Conferma documento gestionale</button></form>`:''}</section><section class="card"><h2>Pagamenti</h2><div class="table-wrap"><table><thead><tr><th>Data</th><th>Metodo</th><th>Importo</th><th>Riferimento</th></tr></thead><tbody>${payRows}</tbody></table></div>${due>0&&i.status!=='draft'&&i.status!=='void'?`<form class="inline-form" method="post" action="/invoices/${i.id}/payments">${formToken(req)}${input('Importo (€)','amount','number',due.toFixed(2),true)}${select('Metodo','method',[['cash','Contanti'],['card','Carta'],['bank_transfer','Bonifico'],['other','Altro']])}${input('Riferimento','reference')}<button class="button primary">Registra pagamento</button></form>`:''}</section>${deliver}`;res.send(page(`Documento ${i.invoice_number}`,body,req.session.user,'invoices'));}catch(e){next(e);}});
